       -I/build/sebor/stdcxx-4.2.1-gcc-4.3.0-8D/include \
       -I/home/sebor/stdcxx-4.2.1/examples/include \
       -pedantic -nostdinc++ -O2   -W -Wall \
       -Wcast-qual -Winline -Wshadow -Wwrite-strings -Wno-long-long -Wcast-align   t.cpp
