column382:
03/Jun/08 01:06;vitek;It looks like this is a problem with gslice. Here is the relevant code.

{noformat}
template <class _TypeT>
valarray<_TypeT>::valarray(const gslice_array<_TypeT>& sl_ar)
{
    gslice __sl(sl_ar._C_get_slice());

    _RW::__rw_array <_TypeT> __tmp =
        _RW::__rw_array <_TypeT>(_TypeT (), __sl.ind_numb());

    _RWSTD_SIZE_T __i = __sl.next_ind();
    _RWSTD_SIZE_T __cpt = 0;

    while (!__sl.is_reseted ())
    {
      __tmp[__cpt] = (*(sl_ar.get_ref_mem_array()))[__i];
      __i = __sl.next_ind();
      __cpt++;
    }

    _C_array.swap (__tmp);
}
{noformat}

The issue is that if you have a gslice with start = 1, step = 1 and stride = 1 the slice {{\_\_sl}} is reset when you call {{next_ind()}} the first time. So we never enter the loop, but we should enter the loop exactly once.

column383:
03/Jun/08 01:21;sebor;This is from the binary incompatible rewrite of {{valarray}} that I've been mentioning for eons (I should finally commit it on trunk). If it fixes this bug it might spark an idea for a compatible fix...

{noformat}
// 26.3.6 - generalized slice of a valarray
class _RWSTD_EXPORT gslice
{
public:

    // 26.3.6.1
    gslice (): _C_imp (0) { /* no-op */ }

    gslice (_RWSTD_SIZE_T,
            const valarray<_RWSTD_SIZE_T>&,
            const valarray<_RWSTD_SIZE_T>&);

    gslice (const gslice&);

    ~gslice ();

    gslice& operator= (const gslice&);

    // 26.3.6.2
    _RWSTD_SIZE_T start () const {
        return _C_imp ? _C_imp->_C_start : 0;
    }

    valarray<_RWSTD_SIZE_T> size () const {
        return _C_imp ? _C_imp->_C_length : valarray<_RWSTD_SIZE_T>();
    }

    valarray<_RWSTD_SIZE_T> stride () const {
        return _C_imp ? _C_imp->_C_stride : valarray<_RWSTD_SIZE_T>();
    }

    const _RWSTD_SIZE_T _C_size () const {
        return _C_imp ? _C_imp->_C_inxs.size () : 0;
    }

    const valarray<_RWSTD_SIZE_T>& _C_indices () const {
        _RWSTD_ASSERT (0 != _C_imp);
        return _C_imp->_C_inxs;
    }

private:

    // referenced counted gslice implementation for efficiency
    struct _Imp {
        _Imp (_RWSTD_SIZE_T,
              const valarray<_RWSTD_SIZE_T>&,
              const valarray<_RWSTD_SIZE_T>&);

        valarray<_RWSTD_SIZE_T> _C_length;   // set of lengths (sizes equal)
        valarray<_RWSTD_SIZE_T> _C_stride;   // set of strides (sizes equal)
        valarray<_RWSTD_SIZE_T> _C_inxs;     // cached array of indices
        _RWSTD_SIZE_T           _C_start;    // starting offset
        _RWSTD_SIZE_T           _C_refs;     // reference count

    private:
        _Imp (const _Imp&);            // not copyable
        void operator=(const _Imp&);   // not assignable
    };

    _Imp *_C_imp;   // reference-counted implementation or 0
};


gslice::_Imp::
_Imp (size_t                  beg,
      const valarray<size_t>& len,
      const valarray<size_t>& str)
    : _C_length (len),
    _C_stride (str),
    _C_inxs (/* initialized below */),
    _C_start (beg),
    _C_refs (0)
{
    _RWSTD_ASSERT (_C_length.size () == _C_stride.size ());

    // compute the number of indices represented by this slice
    // and store it for later so that the expensive computation
    // need only be done at most once
    const size_t length = _C_length.size ();

    if (0 == length)
        return;

    size_t nelems = 1;

    for (size_t i = 0; i != length; ++i) {
        nelems *= _C_length [i];
    }

    _C_inxs.resize (nelems);

    size_t small_cache [256];
    const size_t cache_size = sizeof small_cache / sizeof *small_cache;

    size_t* const cache =
        length < cache_size ? small_cache : new size_t [length];

    memset (cache, 0, length * sizeof *cache);

    _C_inxs [0] = _C_start;

    for (size_t i = 1; i < nelems; ++i) {

        size_t inx = length;

        while (inx && cache [inx - 1] == _C_length [inx - 1] - 1)
            --inx;

        _RWSTD_ASSERT (0 != inx);

        ++cache [inx - 1];
        if (inx < length)
            memset (cache + inx, 0, (length - inx) * sizeof *cache);

        _C_inxs [i] = _C_start;

        for (size_t j = 0; j != inx; ++j)
            _C_inxs [i] += cache [j] * _C_stride [j];
    }

    if (cache != small_cache)
        delete[] cache;
}


gslice::
gslice (size_t                  beg,
        const valarray<size_t>& len,
        const valarray<size_t>& str)
    : _C_imp (new _Imp (beg, len, str))
{
    // no-op
}


gslice::
gslice (const gslice &rhs)
    : _C_imp (rhs._C_imp)
{
    if (_C_imp)
        _RWSTD_ATOMIC_PREINCREMENT (_C_imp->_C_refs, false);
}


gslice::
~gslice ()
{
    if (_C_imp && 0 == _RWSTD_ATOMIC_PREDECREMENT (_C_imp->_C_refs, false))
        delete _C_imp;
}


gslice& gslice::
operator= (const gslice &rhs)
{
    if (_C_imp && 0 == _RWSTD_ATOMIC_PREDECREMENT (_C_imp->_C_refs, false))
        delete _C_imp;

    if (rhs._C_imp)
        _RWSTD_ATOMIC_PREINCREMENT (_C_imp->_C_refs, false);

    return *this;
}
{noformat}

column381:
26/Jun/08 00:26;vitek;A quick peek at {{__rw_get_timepunct()}} in {{time_put.cpp}} and we see this...

{noformat}
        case 'U':   // Sunday-based week number [00..53]
            hib = 53;
            // FIXME: implement
            break;

        case 'W':   // Monday-based week number [00..53]
            hib = 53;
            // FIXME: implement
            break;
{noformat}

The {{%Ex}} format directive expands out to {{%Ow weekday, %OU week, %Oy year}} and we already know that {{%U}} isn't implemented and {{%OU}} requires the same calculation as {{%U}}, but is to be displayed in an alternative format, so the failure is expected. At least until we decide to implement formatting for these directives.

column383:
02/Jun/08 11:31;farid;MSVC (and ICC/Windows) also supports [__declspec (noreturn)|http://msdn.microsoft.com/en-us/library/k6ktzx3s(VS.80).aspx] to indicate that a function doesn't return. But definition #define _RWSTD_ATTRIBUTE_NORETURN __declspec (noreturn) in _config-msvc.h causes an error's:
{noformat}
D:\stdcxx\trunk\include\rw/_defs.h(1158) : error C2144: syntax error : 'int' should be preceded by ';'
D:\stdcxx\trunk\include\rw/_defs.h(1158) : warning C4091: '__declspec(noreturn)' : ignored on left of 'int' when no variable is declared
{noformat}

The possible solution is moving the _RWSTD_ATTRIBUTE_NORETURN in _defs.h header before the function name , i.e.
{noformat}
// called for failed assertions
void _RWSTD_EXPORT _RWSTD_ATTRIBUTE_NORETURN
__rw_assert_fail (const char*, const char*, int, const char*);
{noformat}
or 
{noformat}
// called for failed assertions
_RWSTD_ATTRIBUTE_NORETURN void _RWSTD_EXPORT
__rw_assert_fail (const char*, const char*, int, const char*);
{noformat}

