column387:
07/Apr/08 16:12;sebor;That would be one way of ensuring proper alignment.

The other approach is to use a union:

{noformat}
template <class charT>
void test_moneypunct (charT)
{
    typedef std::moneypunct <charT> PunctT;

    const char fill = '\xdc';

    union {
        void *align;
        char buf [sizeof (PunctT) + 1];
    } buf;
    std::memset (&buf, fill, sizeof (buf));

    PunctT* p = new (buf.buf) PunctT ();
    assert (fill == buf.buf [sizeof (PunctT)]);
{noformat}

