column381:
10/Jan/08 02:35;vitek;It appears that there is some issue with catopen() on AIX. I believe the following testcase can be used to demonstrate.

{noformat}
#include <nl_types.h>
#include <locale.h>
#include <unistd.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

#define _RWSTD_BAD_CATD nl_catd (-1)

int main (int argc, char* argv [])
{
    if (argc < 2) {
        printf ("usage %s <catalog> [locale]\n", argv [0]);
        return 0;
    }

    if (argc > 1) {
        const char* loc = setlocale (LC_ALL, argv [2]);
        if (!loc) printf ("failed to set locale to %s\n", argv [2]);
    }

    const char* const nls = getenv ("NLSPATH");
    printf ("NLSPATH is %s\n", nls ? nls : "not set");

    const char* const lang = getenv ("LANG");
    printf ("LANG    is %s\n", lang ? lang : "not set");

    const nl_catd cat = catopen (argv[1], NL_CAT_LOCALE);
    if (_RWSTD_BAD_CATD == cat) {
        printf ("failed\n");
        return 1;
    }
    else {
        printf ("success\n");
        catclose (cat);
    }

    return 0;
}
{noformat}

Here are the results on AIX and Linux...

{noformat}
$ ./t.aix /nfs/homes/vitek/nls/msgs-aix.cat
NLSPATH is /nfs/homes/vitek/nls/%N
LANG    is not set
success
$ ./t.aix nls/msgs-aix.cat
NLSPATH is /nfs/homes/vitek/nls/%N
LANG    is not set
success
$ ./t.aix msgs-aix.cat
NLSPATH is /nfs/homes/vitek/nls/%N
LANG    is not set
failed


$ ./t.lin /nfs/homes/vitek/nls/msgs-lin.cat
NLSPATH is /nfs/homes/vitek/nls/%N
LANG    is not set
success
$ ./t.lin nls/msgs-lin.cat
NLSPATH is /nfs/homes/vitek/nls/%N
LANG    is not set
success
$ ./t.lin msgs-lin.cat
NLSPATH is /nfs/homes/vitek/nls/%N
LANG    is not set
success
{noformat}

The first run of each series uses an absolute path, the second a relative path, and the last should be using the NLSPATH after replacing %N with the provided filename. Unfortunately that last case doesn't work on AIX.

The documentation for catopen() on AIX claims that setlocale() must be called first if you require that the NLSPATH environment variable be used for catalog lookup. I've tried this using the above testcase, but it doesn't seem to have any effect.

column385:
15/Jan/08 21:21;vitek;Yeah, if I would have looked I would have seen __rw_setlocale. This does make me feel a little better about option (4). This change would allow us to successfully open a message catalog when the locale provided to std::messages<T>::open() was not the C/POSIX locale. Any proposal for what we would do if this is not the case? Maybe just fail?

Here is a test that I believe would fail the second assert because AIX requires LC_MESSAGES to be set to something other than "C".

{noformat}
  const std::locale classic (std::locale::classic ());
  const std::locale en_US ("en_US");

  const std::messages<char>& m = std::use_facet<std::messages<char> >(classic);

  // this would work because we would call setlocale (LC_MESSAGES, "en_US")
  // internally
  std::messages_base::catalog c1 = m.open ("catalog", en_US);
  assert (! (c1 < 0));
  m.close (c1);

  // this would not work because we would call setlocale (LC_MESSAGES, "C")
  // internally, and the NLSPATH lookup is disabled
  std::messages_base::catalog c2 = m.open ("catalog", classic);
  assert (! (c2 < 0));
  m.close (c2);
{noformat}

In that case, I feel like I should use all of 1, 2 and 4.

column381:
12/Nov/07 20:09;farid;The reason of the assertions is that the ctype<char> and ctype<wchar_t> uses the same mask table (__rw_classic_tab in src/ctype.cpp), but MSVC crt uses the different tables for isxxx() and iswxxx() functions in "C" locale.

So that isprint ('\t') == 0; but iswprint (L'\t') == 64;

For the characters >= 0x80 the __rw_classic_tab table inited by  zero values, but CRT isxxx() functions returns non-zero values.

column386:
29/Feb/08 16:46;farid;Hmm, after carefully reading the C99 standard now I think that this behavior is allowed.

The standard says that if isxxx() returns true, then iswxxx() should also return true, but at the same time it doesn't says that if isxxx() returns false, the iswxxx() should return false.

The following test passes, asserting only in assert (-1 != ci); line when i == 255 due to wctob() returns -1:

{code:title=test.cpp}
#include <locale.h>
#include <ctype.h>
#include <wctype.h>
#include <wchar.h>
#include <assert.h>

int main()
{
	setlocale (LC_ALL, "C");

	for (int i = 0; i < 256; ++i) {
		const wint_t wi = btowc (i);
		assert (WEOF != wi);

		const int ci = wctob (wi);
		assert (-1 != ci);

		assert (char (ci) == char (i));

		assert (!!iswalnum (wi)  == !!isalnum (i) || !isalnum (i));
		assert (!!iswalpha (wi)  == !!isalpha (i) || !isalpha (i));
		assert (!!iswcntrl (wi)  == !!iscntrl (i) || !iscntrl (i));
		assert (!!iswdigit (wi)  == !!isdigit (i) || !isdigit (i));
		assert (!!iswlower (wi)  == !!islower (i) || !islower (i));
		assert (!!iswprint (wi)  == !!isprint (i) || !isprint (i));
		assert (!!iswspace (wi)  == !!isspace (i) || !isspace (i));
		assert (!!iswupper (wi)  == !!isupper (i) || !isupper (i));
		assert (!!iswxdigit (wi) == !!isxdigit (i) || !isxdigit (i));
#ifdef _MSC_VER
		// MSVC specific function
		assert (!!iswascii (wi)  == !!isascii (i) || !isascii (i));
#endif

		// does not supported in MSVC
		// assert (!!iswblank (wi)  == !!isblank (i));
		// the result may differ by the standard
		// assert (!!iswgraph (wi)  == !!isgraph (i));
		// the result may differ by the standard
		// assert (!!iswpunct (wi)  == !!ispunct (i));
	}

	return 0;
}
{code}

