#include <stdio.h>
#include <stdlib.h>
#include <fstream>
#include <string>

int main (int argc, char *argv[])
{
    unsigned long loops;
    const char* file;

    loops = 1 < argc ? strtoul (argv [1], 0, 0) : 1;
    file =  2 < argc ? argv [2] : __FILE__;

    unsigned long line_count = 0;
    std::string line;

    for (unsigned long i = 0; i != loops; ++i) {
        std::ifstream in (file);
        if (!in.is_open ())
            return 1;

        while (std::getline (in, line))
            ++line_count;
    }

    printf ("%lu\n", line_count);
}

column383:
30/Jan/08 01:04;vitek;All of the above testcases are testing both the time taken by getline() and the time to create and setup a file stream. The following testcase tests just the time it takes to do the getline, everything else should be constant.


{noformat}
#include <iostream>
#include <fstream>
#include <string>

#include <stdlib.h>

int main (int argc, char* argv[])
{
    size_t loops = 1000;
    if (1 < argc)
        loops = strtoul (argv [1], 0, 0);

    const char* file = __FILE__;
    if (2 < argc)
        file = argv [2];

    std::ifstream ifs (file);
    if (!ifs.is_open ())
        return 1;

    size_t lines = 0;

    std::string line;
    for (size_t i = 0; i < loops; ++i)
    {
        while (std::getline (ifs, line, '\n'))
            ++lines;

        ifs.clear ();
        ifs.seekg (0);
    }

    std::cout << lines << std::endl;
    return 0;
}
{noformat}

